def solve_a(n):
    a = [0] * (n + 1)
    a[1] = 0
    for i in range(2, n + 1):
        max_val = -1
        for j in range(1, i):
            val = a[j] + a[i - j] + min(j, i - j)
            if val > max_val:
                max_val = val
        a[i] = max_val
    return a[n]

